  auto mem_block = segment_meta_->writing_forward_block().value();
  std::string wal_file_path =
      FileHelper::MakeWalPath(path_, segment_meta_->id(), mem_block.id_);
  WalOptions wal_option;
  if (std::filesystem::exists(wal_file_path)) {
